import os
import json
from robot.utils.robottime import timestr_to_secs

from .base import BaseInterface
from ..util import check_bts_id_type
from ..validators import And, IsString, IsOneOf
from ..converter import to_bool


class CommissioningInterface(BaseInterface):

    def validate_scf(self, scf_file, skip_parameter_relation_errors=False, timeout=60, alias="default"):
        """Validate SCF.

        :param string scf_file: SCF file path
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors
        :param float timeout: Time to wait for positive procedure result
        :param string alias: Name of execution context.
        """
        skip_parameter_relation_errors = to_bool(skip_parameter_relation_errors)
        timeout = timestr_to_secs(timeout)
        IsString().check(scf_file)

        parameters = {"skipParameterRelationErrors": skip_parameter_relation_errors}

        return self.store.get(alias).execute_procedure("validateScf", parameters, timeout, input_file_name=scf_file)

    def validate_scf_online(self, scf_file, validation_type, skip_parameter_relation_errors=False, timeout=60, alias="default"):
        """Validate SCF with detected hardware or NIDD and relations.

        :param string scf_file: SCF file path
        :param string validation_type: possible values (NIDD_AND_RELATIONS, DETECTED_HW)
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors
        :param float timeout: Time to wait for positive procedure result
        :param string alias: Name of execution context.
        """
        skip_parameter_relation_errors = to_bool(skip_parameter_relation_errors)
        timeout = timestr_to_secs(timeout)
        IsString().check(scf_file)

        parameters = {"skipParameterRelationErrors": skip_parameter_relation_errors,
                      "validationType": validation_type}

        return self.store.get(alias).execute_customer_procedure("validateScf", parameters, timeout, input_file_name=scf_file)

    def add_rat(self, rat_technology, plan_scf_file, rat_scf_file, output_scf, timeout=60, alias="default"):
        """Add RAT

        :param rat_technology: Name of rat being added
        :param plan_scf_file: SCF file with plan configuration
        :param rat_scf_file: SCF file with rat specific configuration
        :param timeout: Time to wait for positive procedure results
        :param alias: Name of execution context
        :param output_scf: Name of output file
        :return:
        """
        timeout = timestr_to_secs(timeout)

        IsString().check(rat_technology)
        rat_technology = rat_technology.upper()
        IsOneOf("GSM", "WCDMA", "LTE").check(rat_technology)
        parameters = {"ratTechnology": rat_technology}

        IsString().check(plan_scf_file)
        IsString().check(rat_scf_file)

        return self.store.get(alias).execute_offline_procedure("addRat", parameters, timeout,
                                                               plan_scf_file=plan_scf_file, rat_scf_file=rat_scf_file,
                                                               output_file_name=output_scf)

    def migrate_scf(self, input_scf_file, output_scf_file, timeout=60, alias="default"):
        """Migrate SCF

        :param string input_scf_file: Input SCF file path
        :param string output_scf_file: Output SCF file path
        :param float timeout: Time to wait for positive procedure result
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(input_scf_file)
        IsString().check(output_scf_file)
        return self.store.get(alias).execute_offline_procedure(
            "migrateScf", {}, timeout, input_file_name=input_scf_file, output_file_name=output_scf_file)

    def perform_commissioning(
            self, bts_id, scf_file, skip_parameter_relation_errors=False,
            should_activate=True, timeout=300, alias="default", **kwargs):
        """Perform commissioning.

        :param string bts_id: BTS ID
        :param string scf_file: SCF file path
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors
        :param boolean should_activate: should automatically activate plan.
        :param float timeout: Time to wait for positive procedure result
        :param string alias: Name of execution context.
        """
        should_activate = to_bool(should_activate)
        skip_parameter_relation_errors = to_bool(skip_parameter_relation_errors)
        timeout = timestr_to_secs(timeout)
        bts_id = check_bts_id_type(bts_id)
        IsString().check(bts_id)
        IsString().check(scf_file)

        parameters = {"btsId": bts_id, "shouldBeActivated": should_activate}
        if skip_parameter_relation_errors:
            parameters["skipParameterRelationErrors"] = True

        return self.store.get(alias).execute_procedure("downloadPlan", parameters, timeout, input_file_name=scf_file)

    def perform_delta_recommissioning(self, delta_file, skip_parameter_relation_errors=False, should_activate=True, timeout=300, alias="default"):
        """Perform delta recommissioning.

        :param string delta_file: Delta JSON or path to JSON file.
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors.
        :param boolean should_activate: should automatically activate plan.
        :param float timeout: Time to wait for positive procedure result
        :param string alias: Name of execution context.

        | Delta JSON is send to Admin API as "planObjects" parameter of "recomission" procedure.
        | For detailed instruction how to create delta JSON see Admin API doc:
        | https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-recommission.html

        **SAMPLE DELTA:**

        ::

            [
                {
                    "distName": "MRBTS-1/LNBTS-1/LNMME-0",
                    "operation": "update",
                    "parameters": [
                        {
                            "parameterName": "ipAddrPrim",
                            "value": "10.0.1.99",
                            "operation": "update"
                        }
                    ]
                }
            ]
        """
        should_activate = to_bool(should_activate)
        skip_parameter_relation_errors = to_bool(skip_parameter_relation_errors)
        timeout = timestr_to_secs(timeout)
        IsString().check(delta_file)

        if os.path.isfile(delta_file):
            with open(delta_file, 'r') as f:
                delta_file = f.read()

        delta = json.loads(delta_file)
        parameters = {"planObjects": delta, "shouldBeActivated": should_activate}
        if skip_parameter_relation_errors:
            parameters["skipParameterRelationErrors"] = True

        return self.store.get(alias).execute_procedure("recommission", parameters, timeout)

    def perform_parameter_recommissioning(
            self, dist_name, parameter, operation, value, skip_parameter_relation_errors=False, should_activate=True, timeout=300, alias="default"):
        """Perform parameter recommissioning.

        :param string dist_name: Object dist name
        :param string parameter: Parameter name
        :param string operation: Parameter operation (create, update or delete)
        :param string value: Parameter value
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors
        :param float timeout: Time to wait for positive procedure result
        :param string alias: Name of execution context.
        """
        should_activate = to_bool(should_activate)
        skip_parameter_relation_errors = to_bool(skip_parameter_relation_errors)
        timeout = timestr_to_secs(timeout)
        IsString().check(dist_name)
        IsString().check(parameter)
        And(IsString(), IsOneOf("delete", "update", "create")).check(operation)

        parameters = {"distName": dist_name, "parameterName": parameter, "operation": operation, "value": value, "shouldBeActivated": should_activate}
        if skip_parameter_relation_errors:
            parameters["skipParameterRelationErrors"] = True
        return self.store.get(alias).execute_procedure("setParameter", parameters, timeout)

    def activate_plan(self, plan_id, timeout=300, alias="default"):
        """Activate previously commissioned plan.commissioned

        :param string plan_id: Plan ID (delta dist name)
        :param float timeout: Time to wait for positive procedure result
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(plan_id)

        self.store.get(alias).execute_procedure("activatePlan", {"deltaDN": plan_id}, timeout)

    def reset_configuration(self, remove_site_id, remove_security_credentials, timeout=500, alias="default"):
        """Reset configuration.

        :param boolean remove_site_id: Remove Site ID.
        :param boolean remove_security_credentials: Remove security credentials.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        remove_site_id = to_bool(remove_site_id)
        remove_security_credentials = to_bool(remove_security_credentials)
        timeout = timestr_to_secs(timeout)

        self.store.get(alias).execute_procedure(
            "configurationReset", {"removeSiteId": remove_site_id, "removeSecurityCredentials": remove_security_credentials}, timeout)

    def active_ncf(self, scf_file, timeout=300, alias="default"):
        """Activates commissioning of NCF file

        :param string scf_file: input file
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        IsString().check(scf_file)
        timeout = timestr_to_secs(timeout)
        self.store.get(alias).execute_customer_procedure("activeNCF", {}, timeout, input_file_name=scf_file)
